UPDATE sys_validation_flows SET component_config = '{"parse_param": {"json_path": "$"}, "check_format": {"rules": [{"msg": "订单号格式错误，格式应为 ORD+10位数字", "path": "$.orderNo", "type": "REGEX", "pattern": "^ORD[0-9]{10}$"}, {"max": 1000000, "min": 0.01, "msg": "订单金额超出范围(0.01~1000000)", "path": "$.amount", "type": "RANGE"}, {"msg": "用户ID不能为空", "path": "$.userId", "type": "NOT_NULL"}]}, "check_db_user": {"msg": "用户不存在或已被禁用", "sql": "SELECT COUNT(1) FROM gnosis_sample.sys_users WHERE user_id = ? AND status = 1", "type": "DB_QUERY", "param_path": "$.userId"}}' WHERE flow_id = 'ORDER_CREATE_FLOW';